#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>
#include <syslog.h>

#define MAX_QUERY_LEN 2048
#define MAX_FIELD_LEN 256
#define ROLE_ADMIN 0x01
#define ROLE_ANALYST 0x02
#define ROLE_READONLY 0x04

typedef struct {
    char username[64];
    unsigned int roles;
    int session_id;
} db_session_t;

typedef struct {
    char table_name[128];
    char columns[512];
    char where_clause[512];
    char order_by[128];
} query_plan_t;

static void audit_log(const db_session_t *session, const char *action, const char *detail) {
    char log_buf[1024];
    snprintf(log_buf, sizeof(log_buf), "[session=%d user=%s] %s: %s",
             session->session_id, session->username, action, detail);
    syslog(LOG_INFO, "%s", log_buf);
}

static int check_table_access(const db_session_t *session, const char *table) {
    if (session->roles & ROLE_ADMIN) return 1;
    if (strcmp(table, "public_data") == 0) return 1;
    if ((session->roles & ROLE_ANALYST) && strcmp(table, "analytics") == 0) return 1;
    if ((session->roles & ROLE_READONLY) && strcmp(table, "reports") == 0) return 1;
    return 0;
}

static int sanitize_identifier(const char *input, char *output, size_t outlen) {
    size_t i, j = 0;
    for (i = 0; input[i] && j < outlen - 1; i++) {
        char c = input[i];
        if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
            (c >= '0' && c <= '9') || c == '_' || c == '.') {
            output[j++] = c;
        }
    }
    output[j] = '\0';
    return (j > 0) ? 0 : -1;
}

static int build_diagnostic_message(char *buf, size_t buflen,
                                     const char *context, const query_plan_t *plan) {
    int written = snprintf(buf, buflen, "Query diagnostic for context [%s] - ", context);
    if (written < 0 || (size_t)written >= buflen) return -1;

    char *pos = buf + written;
    size_t remaining = buflen - written;

    written = snprintf(pos, remaining, "table=%s cols=%s",
                       plan->table_name, plan->columns);
    return (written < 0) ? -1 : 0;
}

static void emit_driver_error(const db_session_t *session, const char *phase,
                              const char *diagnostic_msg) {
    char error_buf[2048];
    snprintf(error_buf, sizeof(error_buf),
             "DB Driver Error [phase=%s sid=%d]: ", phase, session->session_id);

    size_t prefix_len = strlen(error_buf);
    strncat(error_buf, diagnostic_msg, sizeof(error_buf) - prefix_len - 1);

    /* Log to stderr for driver debugging - uses proper format string */
    fprintf(stderr, "%s", error_buf);
}

int execute_select(db_session_t *session, const char *table,
                   const char *columns, const char *where_cond,
                   const char *order) {
    query_plan_t plan;
    char diag_buf[1024];

    if (!session || !table || !columns) return -1;

    if (sanitize_identifier(table, plan.table_name, sizeof(plan.table_name)) != 0) {
        audit_log(session, "REJECT", "invalid table identifier");
        return -1;
    }

    if (!check_table_access(session, plan.table_name)) {
        audit_log(session, "ACCESS_DENIED", plan.table_name);
        return -1;
    }

    if (sanitize_identifier(columns, plan.columns, sizeof(plan.columns)) != 0) {
        audit_log(session, "REJECT", "invalid column identifier");
        return -1;
    }

    if (where_cond) {
        strncpy(plan.where_clause, where_cond, sizeof(plan.where_clause) - 1);
        plan.where_clause[sizeof(plan.where_clause) - 1] = '\0';
    } else {
        plan.where_clause[0] = '\0';
    }

    if (order) {
        if (sanitize_identifier(order, plan.order_by, sizeof(plan.order_by)) != 0) {
            audit_log(session, "REJECT", "invalid order identifier");
            return -1;
        }
    } else {
        plan.order_by[0] = '\0';
    }

    /* Build and execute query.
     * snprintf returns the number of bytes it WOULD have written; when the
     * output is truncated this can exceed the buffer size. Track the offset
     * safely so that we never compute a negative/underflowed remaining size
     * or advance the write pointer past the end of the buffer. */
    char query[MAX_QUERY_LEN];
    size_t qlen = 0;
    int ret;

    ret = snprintf(query, sizeof(query), "SELECT %s FROM %s",
                   plan.columns, plan.table_name);
    if (ret < 0 || (size_t)ret >= sizeof(query)) {
        audit_log(session, "REJECT", "query construction failure");
        return -1;
    }
    qlen = (size_t)ret;

    if (plan.where_clause[0]) {
        ret = snprintf(query + qlen, sizeof(query) - qlen,
                       " WHERE %s", plan.where_clause);
        if (ret < 0 || (size_t)ret >= sizeof(query) - qlen) {
            audit_log(session, "REJECT", "query construction failure");
            return -1;
        }
        qlen += (size_t)ret;
    }
    if (plan.order_by[0]) {
        ret = snprintf(query + qlen, sizeof(query) - qlen,
                       " ORDER BY %s", plan.order_by);
        if (ret < 0 || (size_t)ret >= sizeof(query) - qlen) {
            audit_log(session, "REJECT", "query construction failure");
            return -1;
        }
        qlen += (size_t)ret;
    }

    /* Simulate query execution failure for demonstration */
    if (strlen(query) > MAX_QUERY_LEN - 100) {
        build_diagnostic_message(diag_buf, sizeof(diag_buf), "query_overflow", &plan);
        emit_driver_error(session, "EXECUTE", diag_buf);
        return -1;
    }

    audit_log(session, "EXECUTE", query);

    /* In real driver: send query to backend, process results */
    printf("Executing: %s\n", query);
    return 0;
}

